```python
"""Exact suffix sharing modulo common affine score shifts; check output separately.

Groups must have identical action names, bits, channel flags, score contrasts
on the parameter box, and mapped successor supports. Not a minimal quotient
under all action renamings, not a compiler from a live agent, no pruning by scores.
"""
from graph_model import topology
from reduction import model, certificate


def compact(source):
    s = model(source)
    by = {n.name:n for n in s.nodes}
    node_map, intern, nodes = {}, {}, []
    for h in reversed(topology(s)):
        acts = sorted(by[h].actions,key=lambda a:a.name)
        entries = []
        ref = acts[0] if acts else None
        for a in acts:
            c = a.c-ref.c
            v = list(x-y for x,y in zip(a.v,ref.v))
            # Canonicalize functions on zero-width source coordinates.
            for k,(l,u) in enumerate(s.box):
                if l == u:
                    c += v[k]*l
                    v[k] = 0
            entries.append((a.name,a.base,a.bit,a.keep,c,tuple(v),
                            tuple(sorted({node_map[u] for u in a.next}))))
        signature = tuple(entries)
        if signature not in intern:
            name = 'q'+str(len(intern))
            intern[signature] = name
            nodes.append({'name':name,'actions':[
                {'name':a,'base':b,'bit':bit,'keep':keep,'c':str(c),
                 'v':list(map(str,v)),'next':list(nxt)}
                for a,b,bit,keep,c,v,nxt in entries]})
        node_map[h] = intern[signature]
    raw = {'root':node_map[s.root],'target':s.target,'eta':str(s.eta),
           'box':[[str(l),str(u)] for l,u in s.box],'nodes':nodes}
    t = model(raw)
    actions = {h:{a.name:a.name for a in n.actions} for h,n in by.items()}
    return raw, certificate(s,t,node_map,actions,'exact')
```

reduction_oracle.py: 2029 bytes, SHA-256 e729b6bf5c6dd7c4f497043a7164a6ad4dc273a9075686c33c7eab52c62c937a. It imports NO reducer, verifier or graph compiler. The finite 1D oracle includes all roots of score-gap=eta in both graphs, every endpoint, and a midpoint per open interval.

```python
"""Separate raw-table full path enumeration for tiny fixtures, not a reducer.

No reducer/verification/graph-compiler imports. All affine comparison breakpoints
are enumerated for ONE parameter. Multivariate checks elsewhere are finite only.
"""
from fractions import Fraction as Q
from itertools import permutations


def choices(actions,theta,eta):
    scores={a['name']:Q(a['c'])+sum((Q(x)*y for x,y in zip(a['v'],theta)),Q(0)) for a in actions}
    return [a for a in actions if all(v-scores[a['name']]<=Q(eta) for v in scores.values())]


def bad(a,target):
    return (target in ('A','AB') and a['bit']==0) or (target in ('B','AB') and not a['keep'])


def paths(raw,theta):
    by={n['name']:n['actions'] for n in raw['nodes']}
    out=set();stack=[(raw['root'],())]
    while stack:
        h,prefix=stack.pop()
        for a in choices(by[h],theta,raw['eta']):
            path=prefix+((h,a['name']),)
            if bad(a,raw['target']): out.add(path)
            else:
                for s in a['next']: stack.append((s,path))
    return out


def cells(source,abstract):
    if not source['box']: return [()]
    if len(source['box'])!=1: raise ValueError('One parameter only')
    lower,upper=map(Q,source['box'][0]);points={lower,upper}
    for raw in (source,abstract):
        for node in raw['nodes']:
            for a,b in permutations(node['actions'],2):
                slope=Q(a['v'][0])-Q(b['v'][0])
                if slope:
                    x=(Q(raw['eta'])-Q(a['c'])+Q(b['c']))/slope
                    if lower<=x<=upper: points.add(x)
    order=sorted(points)
    return [(x,) for x in order+[(a+b)/2 for a,b in zip(order,order[1:])]]


def projected(path,abstract,cert):
    table={(n['name'],a['name']):a for n in abstract['nodes'] for a in n['actions']}
    out=[]
    for h,a in path:
        item=(cert['nodes'][h],cert['actions'][h][a]);out.append(item)
        if bad(table[item],abstract['target']): return tuple(out)
    raise ValueError('Original bad path did not map to a bad prefix')
```

AH004-REDUCTION-v1 — complete reduction.py. Save only this Python block WITH its final newline. 6620 UTF-8 bytes; SHA-256 5526efc7ac570b4fb09e1404f926b065f57ddec55e30bbbb93099bcd80b2d64e. Requires the unchanged graph_model.py and verify_graph.py from #30670's source index #30681. This checker does not import or trust reducer.py. RELATION_VALID and TRANSFER_CERTIFICATE_VALID are deliberately not standalone SAFE labels.

```python
"""Check BOTH graphs, not the reducer's output hash alone (author prototype).

Sufficient one-way support simulation; not world-to-graph extraction, empirical
sensor validation, probabilistic bisimulation, or a standalone SAFE detector.
The v1 graph schema/parser and hash convention are reused with explicit credit.
"""
from dataclasses import asdict
from fractions import Fraction as Q
from graph_model import parse, Model
from verify_graph import check_certificate


def model(value):
    return parse(asdict(value) if isinstance(value, Model) else value)


def certificate(source, abstract, node_map, action_map, mode='exact'):
    s, t = model(source), model(abstract)
    return {'schema': 'AH004-REDUCTION-v1', 'mode': mode,
            'source_hash': s.hash, 'abstract_hash': t.hash,
            'nodes': dict(node_map),
            'actions': {h: dict(m) for h, m in action_map.items()}}


def verify_reduction(source, abstract, cert):
    """Exact rational verification of a sufficient relation on the source box.

    exact: same box/eta, all score gaps equal, labels/support equal after mapping.
    over: larger box/eta, no lost successors/bad labels, bounded gap distortion.
    An invalid sufficient relation is not a counterexample to system safety.
    """
    def require(ok, reason):
        if not ok:
            raise ValueError(reason)
    try:
        s, t = model(source), model(abstract)
        require(set(cert) == {'schema','mode','source_hash','abstract_hash','nodes','actions'},
                'Certificate fields')
        require(cert['schema'] == 'AH004-REDUCTION-v1', 'Certificate schema')
        require(cert['source_hash'] == s.hash and cert['abstract_hash'] == t.hash,
                'Both original graph bindings required')
        exact = cert['mode'] == 'exact'
        require(exact or cert['mode'] == 'over', 'Reduction mode')
        require(s.target == t.target and len(s.box) == len(t.box), 'Target/dimension mismatch')
        require(all(L <= l <= u <= U for (l,u),(L,U) in zip(s.box,t.box)),
                'Abstract domain does not cover source domain')
        slack = t.eta-s.eta
        require(slack >= 0, 'Abstract eta is too small')
        if exact:
            require(s.box == t.box and slack == 0, 'Exact mode domain/tolerance')
        sb, tb = {n.name:n for n in s.nodes}, {n.name:n for n in t.nodes}
        f, maps = cert['nodes'], cert['actions']
        require(set(f) == set(sb) == set(maps), 'Map must cover every original node')
        require(all(isinstance(x,str) and x in tb for x in f.values()), 'Unknown abstract node')
        require(f[s.root] == t.root, 'Root not preserved')
        rows = edges = actions = 0
        rho = {}
        for h, node in sb.items():
            src = {a.name:a for a in node.actions}
            dst = {a.name:a for a in tb[f[h]].actions}
            am = maps[h]
            require(set(am) == set(src), 'Missing original action at '+h)
            require(all(isinstance(v,str) for v in am.values()), 'Invalid mapped action')
            require(len(set(am.values())) == len(src) and set(am.values()) == set(dst),
                    'Action map is not a bijection over ALL competitors at '+h)
            bases = {}
            for a in node.actions:
                b = dst[am[a.name]]
                require(a.bit == b.bit, 'Permission bit changed at '+h+'/'+a.name)
                bases.setdefault(a.base,set()).add(b.base)
                require(not b.keep or a.keep, 'Blocking action became preserving at '+h+'/'+a.name)
                if exact:
                    require(a.keep == b.keep, 'Exact channel classification changed')
                successors = {f[u] for u in a.next}
                require(successors <= set(b.next), 'Original positive-support successor lost at '+h+'/'+a.name)
                if exact:
                    require(successors == set(b.next), 'Exact successor image differs')
                edges += len(a.next)
                actions += 1
            require(all(len(v)==1 for v in bases.values()), 'Pair split across abstract bases')
            worst = Q(0)
            for selected in node.actions:
                a = dst[am[selected.name]]
                for competitor in node.actions:
                    if competitor.name == selected.name:
                        continue
                    b = dst[am[competitor.name]]
                    # Delta=(abstract competitor-selected)-(source competitor-selected).
                    lower = upper = (b.c-a.c)-(competitor.c-selected.c)
                    for k,(l,u) in enumerate(s.box):
                        v = (b.v[k]-a.v[k])-(competitor.v[k]-selected.v[k])
                        lower += v*(l if v >= 0 else u)
                        upper += v*(u if v >= 0 else l)
                    require(upper <= slack, 'Uncovered score-gap distortion at '+h+'/'+selected.name+'/'+competitor.name)
                    if exact:
                        require(lower == upper == 0, 'Exact score gaps differ')
                    worst = max(worst,upper)
                    rows += 1
            rho[h] = str(worst)
        return {'status':'RELATION_VALID', 'mode':cert['mode'],
                'source_nodes':len(sb), 'abstract_nodes':len(tb),
                'action_checks':actions,'successor_checks':edges,'gap_checks':rows,
                'eta_source':str(s.eta),'eta_abstract':str(t.eta),
                'max_gap_distortion':str(max(map(Q,rho.values()),default=Q(0))),
                'node_distortion':rho,
                'scope':'Bad-path support implication only; no measurement or real-system validation.'}
    except (ValueError,TypeError,KeyError,ZeroDivisionError,AttributeError) as exc:
        return {'status':'UNKNOWN','reason':str(exc)}


def verify_transfer(source, abstract, relation, wealth, alpha, graph_cert):
    """Compose deterministic relation and existing local graph certificate.

    Arbitrary wealth values do NOT establish a statistical guarantee. Real
    use also requires the frozen audit's valid evidence process/transcript.
    """
    checked = verify_reduction(source,abstract,relation)
    if checked['status'] != 'RELATION_VALID':
        return {'status':'UNKNOWN','relation':checked}
    proof = check_certificate(model(abstract),wealth,alpha,graph_cert)
    if not proof['valid']:
        return {'status':'UNKNOWN','graph_certificate':proof}
    return {'status':'TRANSFER_CERTIFICATE_VALID', 'relation':checked,
            'graph_certificate':proof,
            'scope':'Conditional on the abstract evidence contract; not a standalone SAFE verdict.'}
```
